// Get the name of the object (singular)
OUString E3dCubeObj::TakeObjNameSingul() const
{
    OUString sName = SvxResId(STR_ObjNameSingulCube3d);

    OUString aName(GetName());
    if (!aName.isEmpty())
    {
        sName += " \'" + aName + "'";
    }
    return sName;
}
